// GitHubServer is the server API for GitHub service.
// All implementations must embed UnimplementedGitHubServer
// for forward compatibility.
//
// GitHub drives the organizations a fake GitHub App is installed on. A GitHub
// App serves many organizations, each of which grants it an installation, so
// unlike Linear's workspace an organization is a collection rather than a
// singleton.
type GitHubServer interface {
	CreateOrganization(context.Context, *GitHubCreateOrganizationRequest) (*GitHubOrganization, error)
	GetOrganization(context.Context, *GitHubGetOrganizationRequest) (*GitHubOrganization, error)
	ListOrganizations(context.Context, *GitHubListOrganizationsRequest) (*GitHubListOrganizationsResponse, error)
	UpdateOrganization(context.Context, *GitHubUpdateOrganizationRequest) (*GitHubOrganization, error)
	// Deleting an organization also drops its members and teams, and revokes the
	// access tokens minted for its installation.
	DeleteOrganization(context.Context, *GitHubDeleteOrganizationRequest) (*emptypb.Empty, error)
	CreateMember(context.Context, *GitHubCreateMemberRequest) (*GitHubMember, error)
	GetMember(context.Context, *GitHubGetMemberRequest) (*GitHubMember, error)
	ListMembers(context.Context, *GitHubListMembersRequest) (*GitHubListMembersResponse, error)
	UpdateMember(context.Context, *GitHubUpdateMemberRequest) (*GitHubMember, error)
	// Deleting a member also drops the team memberships and repository access
	// they hold, as removing someone from an organization does on GitHub.
	DeleteMember(context.Context, *GitHubDeleteMemberRequest) (*emptypb.Empty, error)
	CreateOutsideCollaborator(context.Context, *GitHubCreateOutsideCollaboratorRequest) (*GitHubOutsideCollaborator, error)
	GetOutsideCollaborator(context.Context, *GitHubGetOutsideCollaboratorRequest) (*GitHubOutsideCollaborator, error)
	ListOutsideCollaborators(context.Context, *GitHubListOutsideCollaboratorsRequest) (*GitHubListOutsideCollaboratorsResponse, error)
	UpdateOutsideCollaborator(context.Context, *GitHubUpdateOutsideCollaboratorRequest) (*GitHubOutsideCollaborator, error)
	// Deleting an outside collaborator also drops the repository access they
	// hold.
	DeleteOutsideCollaborator(context.Context, *GitHubDeleteOutsideCollaboratorRequest) (*emptypb.Empty, error)
	CreateTeam(context.Context, *GitHubCreateTeamRequest) (*GitHubTeam, error)
	GetTeam(context.Context, *GitHubGetTeamRequest) (*GitHubTeam, error)
	ListTeams(context.Context, *GitHubListTeamsRequest) (*GitHubListTeamsResponse, error)
	UpdateTeam(context.Context, *GitHubUpdateTeamRequest) (*GitHubTeam, error)
	// Deleting a team also drops its memberships.
	DeleteTeam(context.Context, *GitHubDeleteTeamRequest) (*emptypb.Empty, error)
	CreateTeamMember(context.Context, *GitHubCreateTeamMemberRequest) (*GitHubTeamMember, error)
	GetTeamMember(context.Context, *GitHubGetTeamMemberRequest) (*GitHubTeamMember, error)
	ListTeamMembers(context.Context, *GitHubListTeamMembersRequest) (*GitHubListTeamMembersResponse, error)
	UpdateTeamMember(context.Context, *GitHubUpdateTeamMemberRequest) (*GitHubTeamMember, error)
	DeleteTeamMember(context.Context, *GitHubDeleteTeamMemberRequest) (*emptypb.Empty, error)
	CreateRepository(context.Context, *GitHubCreateRepositoryRequest) (*GitHubRepository, error)
	GetRepository(context.Context, *GitHubGetRepositoryRequest) (*GitHubRepository, error)
	ListRepositories(context.Context, *GitHubListRepositoriesRequest) (*GitHubListRepositoriesResponse, error)
	UpdateRepository(context.Context, *GitHubUpdateRepositoryRequest) (*GitHubRepository, error)
	// Deleting a repository also drops the access it carried, both the
	// collaborators' and the teams'.
	DeleteRepository(context.Context, *GitHubDeleteRepositoryRequest) (*emptypb.Empty, error)
	CreateCollaborator(context.Context, *GitHubCreateCollaboratorRequest) (*GitHubCollaborator, error)
	GetCollaborator(context.Context, *GitHubGetCollaboratorRequest) (*GitHubCollaborator, error)
	ListCollaborators(context.Context, *GitHubListCollaboratorsRequest) (*GitHubListCollaboratorsResponse, error)
	UpdateCollaborator(context.Context, *GitHubUpdateCollaboratorRequest) (*GitHubCollaborator, error)
	DeleteCollaborator(context.Context, *GitHubDeleteCollaboratorRequest) (*emptypb.Empty, error)
	CreateTeamRepository(context.Context, *GitHubCreateTeamRepositoryRequest) (*GitHubTeamRepository, error)
	GetTeamRepository(context.Context, *GitHubGetTeamRepositoryRequest) (*GitHubTeamRepository, error)
	ListTeamRepositories(context.Context, *GitHubListTeamRepositoriesRequest) (*GitHubListTeamRepositoriesResponse, error)
	UpdateTeamRepository(context.Context, *GitHubUpdateTeamRepositoryRequest) (*GitHubTeamRepository, error)
	DeleteTeamRepository(context.Context, *GitHubDeleteTeamRepositoryRequest) (*emptypb.Empty, error)
	CreateOrganizationRole(context.Context, *GitHubCreateOrganizationRoleRequest) (*GitHubOrganizationRole, error)
	GetOrganizationRole(context.Context, *GitHubGetOrganizationRoleRequest) (*GitHubOrganizationRole, error)
	ListOrganizationRoles(context.Context, *GitHubListOrganizationRolesRequest) (*GitHubListOrganizationRolesResponse, error)
	UpdateOrganizationRole(context.Context, *GitHubUpdateOrganizationRoleRequest) (*GitHubOrganizationRole, error)
	// Deleting a role also drops the assignments it carried.
	DeleteOrganizationRole(context.Context, *GitHubDeleteOrganizationRoleRequest) (*emptypb.Empty, error)
	CreateOrganizationRoleTeam(context.Context, *GitHubCreateOrganizationRoleTeamRequest) (*GitHubOrganizationRoleTeam, error)
	GetOrganizationRoleTeam(context.Context, *GitHubGetOrganizationRoleTeamRequest) (*GitHubOrganizationRoleTeam, error)
	ListOrganizationRoleTeams(context.Context, *GitHubListOrganizationRoleTeamsRequest) (*GitHubListOrganizationRoleTeamsResponse, error)
	UpdateOrganizationRoleTeam(context.Context, *GitHubUpdateOrganizationRoleTeamRequest) (*GitHubOrganizationRoleTeam, error)
	DeleteOrganizationRoleTeam(context.Context, *GitHubDeleteOrganizationRoleTeamRequest) (*emptypb.Empty, error)
	CreateOrganizationRoleUser(context.Context, *GitHubCreateOrganizationRoleUserRequest) (*GitHubOrganizationRoleUser, error)
	GetOrganizationRoleUser(context.Context, *GitHubGetOrganizationRoleUserRequest) (*GitHubOrganizationRoleUser, error)
	ListOrganizationRoleUsers(context.Context, *GitHubListOrganizationRoleUsersRequest) (*GitHubListOrganizationRoleUsersResponse, error)
	UpdateOrganizationRoleUser(context.Context, *GitHubUpdateOrganizationRoleUserRequest) (*GitHubOrganizationRoleUser, error)
	DeleteOrganizationRoleUser(context.Context, *GitHubDeleteOrganizationRoleUserRequest) (*emptypb.Empty, error)
	// The rate limit is a singleton, since GitHub meters every installation of
	// an App against the same allowance.
	GetRateLimit(context.Context, *GitHubGetRateLimitRequest) (*GitHubRateLimit, error)
	UpdateRateLimit(context.Context, *GitHubUpdateRateLimitRequest) (*GitHubRateLimit, error)
	mustEmbedUnimplementedGitHubServer()
}

